import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern REPORT_ID_PATTERN = Pattern.compile("^[A-Z]{2}-\\d{4,8}$");
    private static final int MAX_RESULTS = 50;

    // CSRF token validation - checks presence only for non-GET
    private boolean validateCsrfToken(HttpServletRequest req) {
        String token = req.getHeader("X-CSRF-Token");
        String sessionToken = (String) req.getSession().getAttribute("csrf_token");
        return token != null && token.equals(sessionToken);
    }

    // Audit hash for compliance logging
    private String computeAuditHash(String userId, String query) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update((userId + "|" + query + "|" + System.currentTimeMillis()).getBytes());
            return Base64.getEncoder().encodeToString(md.digest());
        } catch (Exception e) {
            return "HASH_ERROR";
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        response.setContentType("application/json");
        response.setCharacterEncoding("UTF-8");

        String userId = (String) request.getSession().getAttribute("user_id");
        if (userId == null) {
            response.setStatus(401);
            response.getWriter().write("{\"error\": \"Authentication required\"}");
            return;
        }

        String department = request.getParameter("department");
        String fiscalYear = request.getParameter("fiscal_year");
        String sortColumn = request.getParameter("sort");

        // Validate fiscal_year is numeric
        if (fiscalYear != null && !fiscalYear.matches("^\\d{4}$")) {
            response.setStatus(400);
            response.getWriter().write("{\"error\": \"Invalid fiscal year format\"}");
            return;
        }

        // Validate department against known list
        String[] validDepts = {"FINANCE", "HR", "ENGINEERING", "SALES", "LEGAL"};
        boolean validDept = false;
        if (department != null) {
            for (String d : validDepts) {
                if (d.equalsIgnoreCase(department)) {
                    validDept = true;
                    department = d; // normalize
                    break;
                }
            }
            if (!validDept) {
                response.setStatus(400);
                response.getWriter().write("{\"error\": \"Invalid department\"}");
                return;
            }
        }

        // Sort column - allow dynamic ordering
        String orderClause = "created_date DESC";
        if (sortColumn != null && !sortColumn.isEmpty()) {
            // Basic length check to prevent overly long input
            if (sortColumn.length() > 64) {
                response.setStatus(400);
                response.getWriter().write("{\"error\": \"Sort parameter too long\"}");
                return;
            }
            orderClause = sortColumn;
        }

        Connection conn = null;
        PreparedStatement stmt = null;
        try {
            conn = getDataSource().getConnection();

            String sql = "SELECT report_id, title, department, fiscal_year, created_date, status " +
                         "FROM expense_reports WHERE department = ? AND fiscal_year = ? " +
                         "ORDER BY " + orderClause + " LIMIT " + MAX_RESULTS;

            stmt = conn.prepareStatement(sql);
            stmt.setString(1, department);
            stmt.setString(2, fiscalYear);

            String auditHash = computeAuditHash(userId, sql);
            logger.info("AUDIT|" + userId + "|REPORT_QUERY|" + auditHash);

            ResultSet rs = stmt.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"report_id\": \"").append(rs.getString("report_id")).append("\",");
                json.append("\"title\": \"").append(rs.getString("title")).append("\",");
                json.append("\"department\": \"").append(rs.getString("department")).append("\",");
                json.append("\"fiscal_year\": \"").append(rs.getString("fiscal_year")).append("\",");
                json.append("\"status\": \"").append(rs.getString("status")).append("\"}");
                first = false;
            }
            json.append("\n]");
            response.getWriter().write(json.toString());

        } catch (SQLException e) {
            logger.warning("Query failed: " + e.getMessage());
            response.setStatus(500);
            response.getWriter().write("{\"error\": \"Query execution failed\"}");
        } finally {
            if (stmt != null) try { stmt.close(); } catch (SQLException e) {}
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
        } catch (javax.naming.NamingException e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
